import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Simulate the random outcome by calling play() multiple times if needed
        // We'll use vm.assume to ensure we can get a win scenario
        // Drive calls to play() until we get a win or reach a limit
        uint256 initialBankBalance = address(c.bank()).balance;
        uint256 initialPot = c.pot();
        vm.deal(address(this), 10 ether);
        // Perform one play() call - we cannot control the outcome, but we can observe it
        c.play{value: 10}();
        // After the call, if the player won (i.e., pot is 0 in reference), the pot should be 0
        // But we don't know if it was a win. We'll check the pot after a win scenario by looking at bank balance change
        // Actually, we need a general rule that holds for all calls: the pot must be 0 after a win.
        // Since we cannot directly observe the win, we can try to force a win by replaying with known block parameters (not possible in fuzz)
        // Instead, use a different approach: after calling play(), check that if the pot is not zero, then the bank balance didn't change (no win).
        // But the rule must be broken by the mutant: the mutant never resets pot, so after a win, pot remains positive.
        // We can assert: after calling play(), either the pot is zero OR the player's balance didn't increase (i.e., no funds transferred).
        // Better: directly assert that after a call, if the pot changed from before, something holds.
        // The simplest general rule: after a call to play(), the pot is either zero or the bank balance increased by 1 (fee).
        // But the bug: after a win, pot > 0, so the rule "pot == 0 or bank balance increased by 1" would still hold for the bug because bank balance increased by 1 on win.
        // We need a rule that fails for the bug. Let's try: after a call to play(), the pot can only be nonzero if the bank balance increased by exactly 1 wei (fee).
        // In the reference, after a win, pot=0 and bank gets fee => bank balance increased (so pot=0). After a loss, pot increases by 10, bank unchanged.
        // So the rule: after play(), (pot == 0) or (bank.balance increased by 1 and pot increased by 10). But the bug: after a win, pot > 0 and bank balance increased by 1, so the rule holds.
        // Instead, we must assert something that is true in reference but false in bug after a win. For example: after a win, pot must be zero.
        // To detect a win, we can look at the caller's balance: if it increased, it was a win.
        // Let's check if the caller (this contract) received money.
        uint256 balanceBefore = address(this).balance;
        uint256 potBefore = c.pot();
        c.play{value: 10}();
        uint256 balanceAfter = address(this).balance;
        uint256 potAfter = c.pot();
        // Rule: If the caller's balance increased (meaning a win occurred), then potAfter must be 0.
        // In the reference: on win, potAfter=0 and balanceAfter increases by (potBefore+10 -1).
        // On loss, balanceAfter decreases by 10, potAfter = potBefore+10.
        // So the rule: (balanceAfter > balanceBefore) implies (potAfter == 0).
        // In the bug: on win, potAfter = potBefore+10 (since not reset), so the implication fails.
        // However, balanceAfter > balanceBefore is also true on win, so we get a counterexample.
        // But this only works for the first play? It works for any play because we compare before/after.
        assertTrue(!(balanceAfter > balanceBefore) || potAfter == 0, "After a win, pot must be zero");
    }
}

